package com.termux.x11; import android.content.Context; import android.view.*; import java.util.*; public class MainActivity extends Context { public static MainActivity focused; public boolean focus=true,connected=true; public int forwarded; public final List<KeyEvent> forwardedEvents=new ArrayList<>(); public final List<String> nativeKeys=new ArrayList<>(); final Set<Integer> held=new HashSet<>(); final Window window=new Window(); public static final Prefs prefs=new Prefs(); public static class Prefs {public final Bool enableAccessibilityServiceAutomatically=new Bool();} public static class Bool {public void put(boolean b){}} public static MainActivity getInstance(){return focused;} public static MainActivity getInstanceWithPressedKey(int k){return focused!=null&&focused.held.contains(k)?focused:null;} public static boolean anyInstanceHasPressedKeys(){return focused!=null&&!focused.held.isEmpty();} public static void clearAllPressedKeys(){if(focused!=null)focused.held.clear();} public boolean shouldInterceptKeys(){return focus;} public boolean hasWindowFocus(){return focus;} public Window getWindow(){return window;} public boolean handleKey(KeyEvent e){forwarded++;forwardedEvents.add(e);return true;} public void markKeyPressed(int k){held.add(k);} public void markKeyReleased(int k){held.remove(k);} public Lorie getLorieView(){return new Lorie();} public class Lorie {public boolean connected(){return connected;} public boolean sendKeyEvent(int scan,int code,boolean down){nativeKeys.add(scan+":"+code+":"+down);return true;}} }
